<template><div><el-alert type="info" :closable="false" :title="bilingual('只结算已结束的 UTC 整周期。订单阶梯按订单数计算；仓储费使用历史期末库存和价格，库位峰值按周期内记录计算。','Only complete, closed UTC periods can be billed. Order tiers use order counts. Storage uses historical closing stock and rates; location peaks use recorded states throughout the period.')" class="mb16" /><el-alert v-if="error" type="error" :title="error" :closable="false" class="mb16" /><el-form ref="formRef" :model="form" :inline="true"><el-form-item :label="bilingual('客户','Client')" prop="client" :rules="rules"><el-select v-model="form.client" :aria-label="bilingual('客户','Client')" filterable remote :remote-method="lookup" style="width:240px"><el-option v-for="option in clients" :key="option.id" :label="option.label" :value="option.id" /></el-select></el-form-item><el-form-item :label="bilingual('结算类型','Billing mode')"><el-select v-model="form.mode" :aria-label="bilingual('结算类型','Billing mode')" style="width:180px"><el-option value="Recurring" :label="bilingual('周期收费','Recurring charges')" /><el-option value="Storage" :label="bilingual('仓储费','Storage charges')" /><el-option value="OrderTier" :label="bilingual('订单量阶梯','Order volume tiers')" /></el-select></el-form-item><el-form-item :label="bilingual('开始日期','From date')" prop="from" :rules="rules"><el-date-picker v-model="form.from" value-format="YYYY-MM-DD" type="date" /></el-form-item><el-form-item :label="bilingual('结束日期','To date')" prop="to" :rules="rules"><el-date-picker v-model="form.to" value-format="YYYY-MM-DD" type="date" /></el-form-item><el-form-item><el-button type="primary" :loading="loading" :disabled="blocked" @click="preview">{{bilingual('预览计算','Preview calculation')}}</el-button></el-form-item></el-form><template v-if="quote"><el-descriptions :column="2" border class="mb16"><el-descriptions-item :label="bilingual('结算期间','Period')">{{quote.from}} — {{quote.to}}</el-descriptions-item><el-descriptions-item :label="bilingual('服务端合计','Server total')">{{quote.amount}}</el-descriptions-item></el-descriptions><el-table :data="quote.entries||[]" border :empty-text="bilingual('没有可结算项目','No billable entries')"><el-table-column type="expand"><template #default="scope"><div class="details" v-if="scope.row.storageEvidence"><p>{{bilingual('按周期末库存和价格核算；查看各项数量、单价和金额后再确认。','Calculated using closing stock and rates. Check quantities, rates and amounts before confirming.')}}</p><el-table :data="scope.row.breakdown" border><el-table-column :label="bilingual('计费项目','Charge item')" min-width="240"><template #default="line">{{storageLineLabel(line.row.description)}}</template></el-table-column><el-table-column prop="quantity" :label="bilingual('计费数量','Billable quantity')" min-width="130" /><el-table-column prop="rate" :label="bilingual('单价','Rate')" min-width="120" /><el-table-column prop="amount" :label="bilingual('金额','Amount')" min-width="120" /></el-table></div><p v-else class="details">{{bilingual('本项目没有仓储明细','No storage details for this entry')}}</p></template></el-table-column><el-table-column prop="description" :label="bilingual('项目','Description')" min-width="220" /><el-table-column :label="bilingual('类型','Type')" min-width="120"><template #default="scope">{{financeOption(scope.row.type)}}</template></el-table-column><el-table-column prop="orderCount" :label="bilingual('订单数','Order count')" width="120" /><el-table-column prop="amount" :label="bilingual('金额','Amount')" width="130" /><el-table-column prop="currency" :label="bilingual('币种','Currency')" width="100" /></el-table><div class="actions"><span>{{bilingual('核对明细后提交才会生成费用。','Charges are created only after you confirm this preview.')}}</span><el-button v-if="canEdit" type="primary" :loading="saving" :disabled="blocked||!quote.entries?.length" @click="commit">{{bilingual('确认生成费用','Confirm charges')}}</el-button></div></template></div></template>
<script setup>
import {computed,reactive,ref,watch,onMounted,toRaw} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import auth from '@/plugins/auth'
import request from '@/utils/request'
import {bilingual,financeOption,storageLineLabel} from '@/warehouse/i18n'
import {getWarehouseLookups} from '@/api/warehouse'
import {financePending,financePendingError,financeBusy,financeRevision,submitFinance} from '@/warehouse/finance'
const form=reactive({client:'',mode:'Recurring',from:'',to:''}),formRef=ref(),clients=ref([]),quote=ref(null),quotedInput=ref(null),loading=ref(false),saving=ref(false),error=ref(''),canEdit=computed(()=>auth.hasPermi('warehouse:finance:edit')),blocked=computed(()=>saving.value||financeBusy.value||!!financePending.value||!!financePendingError.value),rules=[{required:true,message:bilingual('请填写此项','Complete this field'),trigger:['blur','change']}]
let generation=0,lookupGeneration=0
async function lookup(q=''){const ticket=++lookupGeneration;try{const result=await getWarehouseLookups('clients',q);if(ticket===lookupGeneration)clients.value=result.data}catch(e){error.value=e.message}}
async function preview(){if(blocked.value||loading.value||!await formRef.value.validate().catch(()=>false))return;const ticket=++generation,input={...form};loading.value=true;error.value='';quote.value=null;try{const result=await request({url:'/warehouse/finance/billing/preview',method:'post',data:input,headers:{repeatSubmit:false}});if(ticket===generation){quote.value=result.data;quotedInput.value=input}}catch(e){if(ticket===generation)error.value=e.message}finally{if(ticket===generation)loading.value=false}}
async function commit(){if(blocked.value||!canEdit.value||!quote.value?.quoteHash||!quotedInput.value)return;const payload={...structuredClone(toRaw(quotedInput.value)),quoteHash:quote.value.quoteHash,requestId:crypto.randomUUID()};saving.value=true;error.value='';try{try{await ElMessageBox.confirm(bilingual('确认按以上预览生成费用？规则或数据变化时服务器会要求重新预览。','Create charges from this preview? Changed rules or data require a fresh preview.'),bilingual('确认周期结算','Confirm period billing'),{type:'warning',confirmButtonText:bilingual('生成费用','Create charges'),cancelButtonText:bilingual('取消','Cancel')})}catch{return}await submitFinance({label:bilingual('周期结算','Period billing'),url:'/warehouse/finance/billing/commit',method:'post',data:payload});ElMessage.success(bilingual('周期费用已生成','Period charges created'))}catch(e){error.value=e.message;if(e.response?.data?.code===409&&!financePending.value){quote.value=null;quotedInput.value=null}}finally{saving.value=false}}
watch(()=>JSON.stringify(form),()=>{generation++;quote.value=null;quotedInput.value=null;loading.value=false});watch(financeRevision,()=>{quote.value=null;quotedInput.value=null});onMounted(()=>lookup())
</script>
<style scoped>.details{padding:12px 20px}.mb16{margin-bottom:16px}.actions{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-top:20px;flex-wrap:wrap}.actions span{color:var(--el-text-color-secondary);font-size:13px}</style>
